import * as mupdf from './vendor/mupdf/mupdf.js';
const sources=new Map();
const writeOptions={compress:true,garbage:4,encrypt:'none'};
function bytes(doc,options={}){const buffer=doc.saveToBuffer({...writeOptions,...options});try{return buffer.asUint8Array().slice()}finally{buffer.destroy()}}
function color(hex){return [1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)/255)}
function clonePage(out,source,index){const map=out.newGraftMap();const at=out.countPages();map.graftPage(-1,source,index);const original=source.findPage(index);const annots=original.get('Annots');if(annots.isArray()){const list=out.newArray();annots.forEach(a=>{if(a.get('Subtype').asName()==='Widget')return;const item=out.newDictionary();a.forEach((value,key)=>{if(!['P','Parent','Popup','IRT'].includes(key))item.put(key,map.graftObject(value))});list.push(out.addObject(item))});out.findPage(at).put('Annots',list)}map.destroy()}
function appendText(doc,page,op){const fontName=/[^\x00-\xff]/.test(op.text)?'ja':op.font||'Helvetica';const font=new mupdf.Font(fontName);try{const object=page.getObject();let resources=object.getInheritable('Resources');if(resources.isNull())resources=doc.newDictionary();object.put('Resources',resources);let fonts=resources.get('Font');if(fonts.isNull()){fonts=doc.newDictionary();resources.put('Font',fonts)}const key='pdf.fjtd.dev'+Math.random().toString(36).slice(2,10);fonts.put(key,doc.addFont(font));const inv=mupdf.Matrix.invert(page.getTransform());const rgb=color(op.color||'#393239');let stream=`q ${inv.join(' ')} cm\n${rgb.join(' ')} rg\nBT /${key} ${op.size} Tf\n`;let y=op.y;for(const line of op.text.split('\n')){let glyphs='';for(const ch of line){const gid=font.encodeCharacter(ch.codePointAt(0));if(gid===0&&ch!=='\u0000')throw Error('この文字に対応するフォントがありません。');glyphs+=gid.toString(16).padStart(4,'0')}stream+=`1 0 0 -1 ${op.x} ${y} Tm <${glyphs}> Tj\n`;y+=op.size*1.35}stream+='ET Q\n';const old=object.get('Contents');const contents=doc.newArray();if(old.isArray())old.forEach(v=>contents.push(v));else if(!old.isNull())contents.push(old);contents.push(doc.addStream(stream,{}));object.put('Contents',contents)}finally{font.destroy()}}
function redact(page,rect,black,replace=false){const overlap=(a,b)=>a[0]<b[2]&&a[2]>b[0]&&a[1]<b[3]&&a[3]>b[1];if(!replace)for(const a of page.getAnnotations())if(overlap(a.getBounds(),rect))page.deleteAnnotation(a);const a=page.createAnnotation('Redact');a.setRect(rect);page.applyRedactions(black,replace?0:2,replace?0:2,0)}
function annotate(page,op){const type={highlight:'Highlight',underline:'Underline',strike:'StrikeOut',rectangle:'Square',ellipse:'Circle',ink:'Ink',comment:'Text'}[op.kind];const a=page.createAnnotation(type);a.setColor(color(op.color));a.setAuthor('pdf.fjtd.dev');if(op.kind==='comment'){a.setRect([op.x,op.y,op.x+22,op.y+22]);a.setContents(op.text);a.setIcon('Note')}else if(['highlight','underline','strike'].includes(op.kind)){const r=op.rect;a.setQuadPoints([[r[0],r[1],r[2],r[1],r[0],r[3],r[2],r[3]]]);if(op.kind==='highlight')a.setOpacity(.4)}else if(op.kind==='ink'){a.setInkList([op.points]);a.setBorderWidth(op.width||2)}else{a.setRect(op.rect);a.setBorderWidth(op.width||2)}a.update()}
function compose(model){const source=sources.get(model.source);if(!source)throw Error('元ファイルがありません。');const doc=new mupdf.PDFDocument();try{clonePage(doc,source.doc,model.index);for(const op of model.ops){let page=doc.loadPage(0);try{if(op.kind==='rotate')page.getObject().put('Rotate',op.angle);else if(op.kind==='crop')page.setPageBox('CropBox',op.rect);else if(op.kind==='text')appendText(doc,page,op);else if(op.kind==='replace'){redact(page,op.rect,false,true);page.destroy();page=doc.loadPage(0);if(op.text)appendText(doc,page,op)}else if(op.kind==='redact')redact(page,op.rect,true);else annotate(page,op)}finally{page.destroy()}}return doc}catch(e){doc.destroy();throw e}}
function textLines(page){let current=null;const lines=[];const text=page.toStructuredText();try{text.walk({beginLine(bbox,wmode,direction){current={rect:bbox,text:'',size:12,x:bbox[0],y:bbox[3],direction,wmode};lines.push(current)},onChar(ch,origin,font,size,quad,c){if(current.text===''){current.x=origin[0];current.y=origin[1];current.size=size;current.fontName=font.getName();const rgb=c.length===1?[c[0],c[0],c[0]]:c.length===4?[(1-c[0])*(1-c[3]),(1-c[1])*(1-c[3]),(1-c[2])*(1-c[3])]:c;current.color='#'+rgb.slice(0,3).map(v=>Math.round(Math.max(0,Math.min(1,v))*255).toString(16).padStart(2,'0')).join('')}current.text+=ch},endLine(){current=null}})}finally{text.destroy()}return lines.filter(l=>l.text.trim())}
function renderModel(model,scale=1,details=true){const doc=compose(model);let page,pixmap;try{page=doc.loadPage(0);const bounds=page.getBounds();const width=bounds[2]-bounds[0],height=bounds[3]-bounds[1];scale=Math.min(scale,3000/width,3000/height);pixmap=page.toPixmap(mupdf.Matrix.scale(scale,scale),mupdf.ColorSpace.DeviceRGB,false,true);return {png:pixmap.asPNG(),width,height,lines:details?textLines(page):[],annotations:details?page.getAnnotations().map((a,i)=>({index:i,type:a.getType(),text:a.getContents(),rect:a.getBounds()})):[]}}finally{pixmap?.destroy();page?.destroy();doc.destroy()}}
function openFile({id,data,password}){const doc=new mupdf.PDFDocument(data);try{if(doc.needsPassword()&&!doc.authenticatePassword(password||'')){doc.destroy();return{locked:true}}doc.disableJS();if(!doc.countPages())throw Error('ページのないPDFです。');sources.set(id,{doc});const pages=[];for(let i=0;i<doc.countPages();i++){const p=doc.loadPage(i);const r=((p.getObject().getInheritable('Rotate').asNumber()%360)+360)%360;pages.push({index:i,rotation:r});p.destroy()}return {locked:false,pages}}catch(e){doc.destroy();throw e}}
function savePdf({pages,password}){if(!pages.length)throw Error('保存するページがありません。');const doc=new mupdf.PDFDocument();try{for(const model of pages){const one=compose(model);try{clonePage(doc,one,0)}finally{one.destroy()}}if(password){if(new TextEncoder().encode(password).length>127)throw Error('パスワードはUTF-8で127バイト以下にしてください。');const owner=Array.from(crypto.getRandomValues(new Uint8Array(24)),v=>v.toString(16).padStart(2,'0')).join('');return bytes(doc,{'encrypt':'aes-256','user-password':password,'owner-password':owner})}return bytes(doc)}finally{doc.destroy()}}
const escape=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function convert({pages,format,scale=1.5,language='ja'}){if(format==='txt'||format==='html-text'){let result=[];for(const model of pages){const doc=compose(model);const p=doc.loadPage(0);const s=p.toStructuredText();try{result.push(s.asText())}finally{s.destroy();p.destroy();doc.destroy()}}if(format==='txt')return {text:result.join('\n\n--- PAGE ---\n\n'),mime:'text/plain;charset=utf-8',extension:'txt'};return {text:'<!doctype html><html lang="'+(language==='en'?'en':'ja')+'"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>PDF text</title><style>body{max-width:900px;margin:40px auto;padding:20px;font-family:sans-serif}section{white-space:pre-wrap;line-height:1.8;border-bottom:1px solid #ddd;padding:24px 0}</style>'+result.map(t=>'<section>'+escape(t)+'</section>').join('')+'</html>',mime:'text/html;charset=utf-8',extension:'html'}}const files=[];let convertedBytes=0;for(let i=0;i<pages.length;i++){const doc=compose(pages[i]);let p,pix;try{p=doc.loadPage(0);const b=p.getBounds();const k=Math.min(scale,4000/(b[2]-b[0]),4000/(b[3]-b[1]));pix=p.toPixmap(mupdf.Matrix.scale(k,k),mupdf.ColorSpace.DeviceRGB,false,true);files.push({bytes:format==='jpg'?pix.asJPEG(90):pix.asPNG(),extension:format==='jpg'?'jpg':'png',width:pix.getWidth(),height:pix.getHeight()});convertedBytes+=files[files.length-1].bytes.length;if(convertedBytes>50*1024*1024)throw Error('変換データが50MBを超えました。解像度を下げるかページを分けてください。');}finally{pix?.destroy();p?.destroy();doc.destroy()}}if(format==='html'){let html='<!doctype html><html lang="'+(language==='en'?'en':'ja')+'"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>PDF pages</title><style>body{margin:0;background:#eee}img{display:block;max-width:100%;height:auto;margin:20px auto;box-shadow:0 2px 12px #0002}@media print{body{background:white}img{margin:0;break-after:page;box-shadow:none}}</style></head><body>';for(const f of files){let binary='';for(let i=0;i<f.bytes.length;i+=32768)binary+=String.fromCharCode(...f.bytes.subarray(i,i+32768));html+=`<img alt="PDF page" width="${f.width}" height="${f.height}" src="data:image/png;base64,${btoa(binary)}">`}return {text:html+'</body></html>',mime:'text/html;charset=utf-8',extension:'html'}}return {files}}
function imagePdf({images}){const doc=new mupdf.PDFDocument();try{for(const data of images){const image=new mupdf.Image(data);try{const w=image.getWidth(),h=image.getHeight();const x=doc.addImage(image);doc.insertPage(-1,doc.addPage([0,0,w,h],0,{XObject:{Im:x}},`q ${w} 0 0 ${h} 0 0 cm /Im Do Q`))}finally{image.destroy()}}return bytes(doc)}finally{doc.destroy()}}
export const actions={release:({id})=>{sources.get(id)?.doc.destroy();sources.delete(id);return true},open:openFile,render:({page,scale,details})=>renderModel(page,scale,details),save:savePdf,convert,images:imagePdf,clear:()=>{for(const s of sources.values())s.doc.destroy();sources.clear();return true}};
